import type { BeadColor } from "./palette";
import { quantizePixels, type PatternGrid, type PixelateOptions } from "../../src/data/pixel-engine-core";
export { quantizePixels } from "../../src/data/pixel-engine-core";
export type { PatternGrid, PixelateOptions } from "../../src/data/pixel-engine-core";

interface WorkerRequest {
  pixels: ArrayBuffer;
  width: number;
  height: number;
  options: PixelateOptions;
}

function gridDimensions(sourceWidth: number, sourceHeight: number, size: number): { width: number; height: number } {
  const longSide = Math.max(8, Math.round(Number.isFinite(size) ? size : 256));
  const landscape = sourceWidth >= sourceHeight;
  return {
    width: landscape ? longSide : Math.max(8, Math.round(longSide * sourceWidth / sourceHeight)),
    height: landscape ? Math.max(8, Math.round(longSide * sourceHeight / sourceWidth)) : longSide,
  };
}

/**
 * Shrinks large photos in several high-quality steps. A single 3000px -> 128px
 * canvas draw loses small eyes, hair strands and clothing edges too early.
 */
function samplePixels(
  image: CanvasImageSource,
  sourceWidth: number,
  sourceHeight: number,
  width: number,
  height: number,
  preserveHardEdges: boolean,
): Uint8ClampedArray {
  let current: CanvasImageSource = image;
  let currentWidth = sourceWidth;
  let currentHeight = sourceHeight;

  if (!preserveHardEdges) {
    while (currentWidth > width * 2 || currentHeight > height * 2) {
      const nextWidth = Math.max(width, Math.round(currentWidth / 2));
      const nextHeight = Math.max(height, Math.round(currentHeight / 2));
      const step = document.createElement("canvas");
      step.width = nextWidth;
      step.height = nextHeight;
      const stepContext = step.getContext("2d");
      if (!stepContext) break;
      stepContext.imageSmoothingEnabled = true;
      stepContext.imageSmoothingQuality = "high";
      stepContext.drawImage(current, 0, 0, currentWidth, currentHeight, 0, 0, nextWidth, nextHeight);
      current = step;
      currentWidth = nextWidth;
      currentHeight = nextHeight;
    }
  }

  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) throw new Error("当前浏览器不支持图像处理");
  context.imageSmoothingEnabled = !preserveHardEdges;
  if (!preserveHardEdges) context.imageSmoothingQuality = "high";
  context.drawImage(current, 0, 0, currentWidth, currentHeight, 0, 0, width, height);
  return context.getImageData(0, 0, width, height).data;
}

export function pixelateImage(
  image: CanvasImageSource,
  sourceWidth: number,
  sourceHeight: number,
  options: PixelateOptions,
): PatternGrid {
  const { width, height } = gridDimensions(sourceWidth, sourceHeight, options.size);
  const data = samplePixels(image, sourceWidth, sourceHeight, width, height, Boolean(options.preserveHardEdges));
  return quantizePixels(data, width, height, options);
}

export async function pixelateImageAsync(
  image: CanvasImageSource,
  sourceWidth: number,
  sourceHeight: number,
  options: PixelateOptions,
  signal?: AbortSignal,
): Promise<PatternGrid> {
  const { width, height } = gridDimensions(sourceWidth, sourceHeight, options.size);
  if (Math.max(width, height) < 100 || typeof Worker === "undefined") {
    return pixelateImage(image, sourceWidth, sourceHeight, options);
  }
  const pixels = samplePixels(image, sourceWidth, sourceHeight, width, height, Boolean(options.preserveHardEdges));
  const worker = new Worker(new URL("./pixel-worker.ts", import.meta.url), { type: "module" });
  return new Promise<PatternGrid>((resolve, reject) => {
    const abort = () => {
      worker.terminate();
      reject(signal?.reason instanceof Error ? signal.reason : new DOMException("已取消过期的图像处理", "AbortError"));
    };
    if (signal?.aborted) return abort();
    signal?.addEventListener("abort", abort, { once: true });
    worker.onmessage = (event: MessageEvent<{ grid?: PatternGrid; error?: string }>) => {
      signal?.removeEventListener("abort", abort);
      worker.terminate();
      if (event.data.grid) resolve(event.data.grid);
      else reject(new Error(event.data.error ?? "大图处理失败"));
    };
    worker.onerror = () => {
      signal?.removeEventListener("abort", abort);
      worker.terminate();
      try { resolve(pixelateImage(image, sourceWidth, sourceHeight, options)); }
      catch { reject(new Error("大图处理 Worker 启动失败")); }
    };
    const request: WorkerRequest = { pixels: pixels.buffer, width, height, options };
    worker.postMessage(request, [pixels.buffer]);
  });
}

export function createDemoGrid(size = 48): PatternGrid {
  const width = size;
  const height = size;
  const cells: Array<string | null> = new Array(width * height).fill("A10");
  const set = (x: number, y: number, code: string | null) => {
    if (x >= 0 && y >= 0 && x < width && y < height) cells[y * width + x] = code;
  };
  const ellipse = (cx: number, cy: number, rx: number, ry: number, code: string) => {
    for (let y = 0; y < height; y += 1) {
      for (let x = 0; x < width; x += 1) {
        const d = ((x - cx) / rx) ** 2 + ((y - cy) / ry) ** 2;
        if (d <= 1) set(x, y, code);
      }
    }
  };

  ellipse(24, 27, 13, 16, "A4");
  ellipse(18, 11, 7, 8, "B3");
  ellipse(30, 11, 7, 8, "B3");
  ellipse(18, 12, 4, 6, "C5");
  ellipse(30, 12, 4, 6, "C5");
  ellipse(24, 27, 12, 15, "A4");
  ellipse(24, 38, 9, 5, "A4");
  ellipse(19, 25, 2, 3, "B3");
  ellipse(29, 25, 2, 3, "B3");
  ellipse(24, 29, 2, 1, "B3");
  ellipse(18, 30, 2, 1, "C5");
  ellipse(30, 30, 2, 1, "C5");
  for (let x = 17; x <= 31; x += 1) set(x, 43, "B3");
  for (let y = 32; y <= 42; y += 1) {
    set(15, y, "B3");
    set(33, y, "B3");
  }
  for (let y = 20; y <= 40; y += 1) {
    set(11, y, "B3");
    set(37, y, "B3");
  }
  for (let i = 0; i < 7; i += 1) {
    set(7 + i, 19 - i, "B3");
    set(41 - i, 19 - i, "B3");
  }
  return { width, height, cells };
}

export function createBlankGrid(size = 48): PatternGrid {
  return { width: size, height: size, cells: new Array(size * size).fill(null) };
}

/**
 * One-way compatibility map for browser drafts created by the retired demo
 * palette. Targets were selected from the pinned MARD 291 dataset using the
 * legacy color-matching behavior; names/codes were not reused.
 */
const LEGACY_CODE_MAP: Record<string, string> = {
  M01: "H2", M02: "A21", M03: "F21", M04: "A19", M05: "M11",
  M06: "D9", M07: "C24", M08: "C22", M09: "B28", M10: "B8",
  M11: "R21", M12: "G17", M13: "H3", M14: "H5", M15: "H6",
  M16: "P12", A01: "C18", R08: "A19", P06: "F14", Y04: "A20",
  B17: "C5", G11: "P6", V09: "D18", W02: "H19", R12: "F25",
};

export const LEGACY_GRID_MIGRATION_VERSION = "legacy-demo-to-mard-291-v1@1";

const UNRELIABLE_LEGACY_CODES = new Set(["M05", "M10", "M14", "V09"]);

export interface LegacyGridMigrationEntry {
  oldCode: string;
  newCode: string;
  count: number;
  reliable: boolean;
}

export interface LegacyGridMigrationPlan {
  isLegacy: boolean;
  requiresConfirmation: boolean;
  entries: LegacyGridMigrationEntry[];
  migratedGrid: PatternGrid;
}

export interface LegacyGridMigrationOptions {
  /** The saved draft predates paletteContractVersion=1 and must not be interpreted as current codes. */
  unversioned?: boolean;
}

/** Builds an auditable migration plan without mutating or silently remapping the grid. */
export function planLegacyGridMigration(grid: PatternGrid, options: LegacyGridMigrationOptions = {}): LegacyGridMigrationPlan {
  const hasLegacySignature = grid.cells.some((code) => code !== null
    && (/^[A-Z]+0\d$/.test(code) || code === "V09" || code === "W02" || UNRELIABLE_LEGACY_CODES.has(code)));
  if (!options.unversioned && !hasLegacySignature) {
    return { isLegacy: false, requiresConfirmation: false, entries: [], migratedGrid: grid };
  }
  const counts = new Map<string, number>();
  for (const code of grid.cells) {
    if (code && (options.unversioned || LEGACY_CODE_MAP[code])) counts.set(code, (counts.get(code) ?? 0) + 1);
  }
  const entries = [...counts.entries()].map(([oldCode, count]) => ({
    oldCode,
    newCode: LEGACY_CODE_MAP[oldCode] ?? oldCode,
    count,
    reliable: Boolean(LEGACY_CODE_MAP[oldCode]) && !UNRELIABLE_LEGACY_CODES.has(oldCode),
  }));
  return {
    isLegacy: true,
    // Every unversioned draft needs an explicit decision, including codes such
    // as G11 that are valid in both catalogs but represent different colors.
    requiresConfirmation: Boolean(options.unversioned) || entries.some((entry) => !entry.reliable),
    entries,
    migratedGrid: { ...grid, cells: grid.cells.map((code) => code ? LEGACY_CODE_MAP[code] ?? code : null) },
  };
}

export function countMaterials(grid: PatternGrid, palette: BeadColor[]): Array<BeadColor & { quantity: number }> {
  const counts = new Map<string, number>();
  for (const code of grid.cells) {
    if (code) counts.set(code, (counts.get(code) ?? 0) + 1);
  }
  return palette
    .filter((color) => counts.has(color.code))
    .map((color) => ({ ...color, quantity: counts.get(color.code) ?? 0 }))
    .sort((a, b) => b.quantity - a.quantity);
}

export function fillRegion(grid: PatternGrid, start: number, nextCode: string | null): PatternGrid {
  const target = grid.cells[start];
  if (target === nextCode) return grid;
  const cells = [...grid.cells];
  const queue = [start];
  const seen = new Set<number>([start]);
  while (queue.length) {
    const index = queue.shift()!;
    if (cells[index] !== target) continue;
    cells[index] = nextCode;
    const x = index % grid.width;
    const y = Math.floor(index / grid.width);
    const neighbors = [
      x > 0 ? index - 1 : -1,
      x < grid.width - 1 ? index + 1 : -1,
      y > 0 ? index - grid.width : -1,
      y < grid.height - 1 ? index + grid.width : -1,
    ];
    for (const neighbor of neighbors) {
      if (neighbor >= 0 && !seen.has(neighbor) && cells[neighbor] === target) {
        seen.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
  return { ...grid, cells };
}
